style.css:
/* Global reset to ensure no inherited styles interfere */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

/* Set background color to white and text color to black */
body {
  background-color: white;
  color: black;
  font-family: Arial, sans-serif; /* You can change this to your preferred font */
}

/* Set background color for all page elements, including headers, footers, etc. */
header, footer, section, article, aside, div {
  background-color: white;
  color: black;
}

/* Additional styling for links */
a {
  color: black;
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

/* Example of styling for headers */
h1, h2, h3, h4, h5, h6 {
  color: black;
}

/* Customize text inside paragraphs */
p {
  color: black;
}
